import re
from taf.rfrl.bts.devices.du.cell_operations import GnbCellOperations
from taf.rfrl.ue.exceptions import BadTputFormat
from ute_ue.utils.param_checker import tput_user_value2normalized


class Calculator(object):
    """Class contains calculator for throughput test"""
    def __init__(self):
        """
        Constructor of Calculator class.
        """

    def calculate_tput_per_stream(self, parallel_streams_number, total_tput):
        """
        Return throughput per stream
        :param parallel_streams_number: Number of streams
        :param total_tput: Tput for all streams
        :return: Tput per stream
        """
        tput_raw = re.search(r'(?P<TPUT_VALUE>^[\d.]+) (?P<TPUT_UNIT>\D+)', total_tput)
        if tput_raw:
            tput_per_stream = round(float(tput_raw.group('TPUT_VALUE')) // int(parallel_streams_number), 2)
        else:
            raise BadTputFormat('Invalid throughput string: {}, eg: 100 MBytes/sec'.format(total_tput))
        return str('{} {}').format(tput_per_stream, tput_raw.group('TPUT_UNIT'))

    def calculate_throughput_for_all_cells_based_on_one_cell(self, cell_tput, bts_id=0, du_id=0):
        """
        Calculate throughput for all cells in setup by multiplying cell_throughput by number of cells.

        :param cell_tput: throughput for one cell example "10 Mbits/s"
        :param bts_id: ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: throughput or all cells, for example "20 Mbits/s"
        """
        tp_one_cell = 0
        tp_unit = ""
        nr_of_cells = GnbCellOperations().get_number_of_cells(bts_id=bts_id, du_id=du_id)
        m = re.search(r"(?P<TPUT>\d+\.\d+)\s+(?P<UNIT>\S+)", cell_tput)
        if m:
            tp_one_cell = float(m.group("TPUT"))
            tp_unit = m.group("UNIT")
        else:
            m = re.search(r"(?P<TPUT>\d+)\s+(?P<UNIT>\S+)", cell_tput)
            if m:
                tp_one_cell = int(m.group("TPUT"))
                tp_unit = m.group("UNIT")
        total_tp = "{} {}".format(tp_one_cell * nr_of_cells, tp_unit)
        return total_tp

    def calculate_admissible_tput_value(self, deviation, tput):
        """
            Calculate minimal admissible throughput value for given deviation.

            :param deviation: deviation value "10 %"
            :param tput: throughput value "4340 Mbits/sec"
            :return: dict with admissible throughput value, for example "{'min': 3900000.0, 'max':4500000.0}"
        """
        deviation_value = float(deviation.rstrip('%')) / 100
        normalized_tput = tput_user_value2normalized(tput)
        return {'min': normalized_tput * (1 - deviation_value), 'max': normalized_tput * (1 + deviation_value)}
